import { sha256 } from '@noble/hashes/sha2.js';
import {
  DEFAULT_HEADER_STYLES,
  DEFAULT_NODE_LABELS,
  DEFAULT_STYLES,
} from './constants.js';

/**
 *
 * @param {String} str - The string to be hashed.
 * @param {Number} length - The desired length of the hash.
 * @returns {String} - The generated hash.
 * @example
 * // Hash a string with default length
 * const hash = generateHash('exampleString');
 * console.log(hash); // '1a2b3c4d5e6f7g8h9i0j1k2l3m4n5o6p'
 */
export const generateHash = (str, length = 64) => {
  const hashArray = sha256(new TextEncoder().encode(str)); // Convert string to Uint8Array and hash it
  const hashHex = Array.from(hashArray)
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('')
    .slice(0, length);

  // Randomly mix uppercase and lowercase characters
  return hashHex
    .split('')
    .map((char) =>
      Math.random() < 0.5 ? char.toUpperCase() : char.toLowerCase(),
    )
    .join('');
};

/**
 *
 * @param {Number} length - The length of the random string to be generated.
 * @param {Boolean} includeTimestamp - Whether to include a timestamp in the generated string.
 * @returns {String} - The generated random string.
 * @example
 * // Generate a random string of length 10
 * const randomString = secureRandomString(10);
 * console.log(randomString); // 'aBcDeFgH12'
 */
export const secureRandomString = (length, includeTimestamp = false) => {
  const secureChars =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

  // Generate a secure random string
  let randomPart = Array.from(
    { length },
    () => secureChars[Math.floor(Math.random() * secureChars.length)],
  ).join('');

  // Append timestamp if required
  if (includeTimestamp) {
    const uniquePart = Date.now().toString(); // Current timestamp in milliseconds
    return randomPart + uniquePart;
  }

  return randomPart;
};

const allowedGroupNodes = ['subtopicGroup', 'topicGroup'];

/**
 *
 * @param {String} nodeType - The type of node to be created.
 * @param {String} userId - The ID of the user creating the node.
 * @param {Object} position - The initial position of the node on the canvas.
 * @param {Boolean} selected - Whether the node is selected by default.
 * @param {Boolean} draggable - Whether the node is draggable.
 * @param {Boolean} convertible - Whether the node is convertible. Used when we want to convert a single node to a group node and vice versa.
 * @param {Object} additionalProps - Additional properties to be added to the node.
 * @returns {Object} - The created node object.
 * @example
 * // Create a new node of type 'topic'
 * const newNode = createNewNode('topic', 'user123', { x: 100, y: 200 });
 * console.log(newNode); // { id: '1a2b3c4d5e6f7g8h9i0j1k2l3m4n5o6p', type: 'topic', ... }
 */
export const createNewNode = (
  nodeType,
  userId,
  position = { x: 0, y: 0 },
  selected = true,
  draggable = true,
  convertible = false,
  additionalProps = {},
) => {
  const currentTime = `${Date.now()}`;
  const newNodeId = generateHash(
    `${userId}#${nodeType}#${currentTime}#${secureRandomString(20)}`,
    32,
  );
  const newNode = {
    id: newNodeId,
    type: nodeType,
    position: position,
    data: {
      label: DEFAULT_NODE_LABELS[nodeType],
      style: DEFAULT_STYLES[nodeType],
      ...(allowedGroupNodes.includes(nodeType) && {
        headerStyle:
          additionalProps?.headerStyle ||
          DEFAULT_HEADER_STYLES[nodeType] ||
          DEFAULT_HEADER_STYLES['default'],
      }),
      convertible: convertible,
    },
    selected: selected,
    draggable: draggable,
    ...additionalProps,
  };

  return newNode;
};

/**
 *
 * @param {Object} node - The node to be converted.
 * @param {String} newNodeType - The new type of node to be created.
 * @param {String} userId - The ID of the user creating the node.
 * @param {Object} position - The initial position of the node on the canvas.
 * @param {Boolean} selected - Whether the node is selected by default.
 * @param {Boolean} draggable - Whether the node is draggable.
 * @param {Object} additionalProps - Additional properties to be added to the node.
 * @example
 * // Convert a node to a topicGroup
 * const convertedNode = convertANode(node, 'topicGroup', 'user123', { x: 100, y: 200 });
 * console.log(convertedNode); // { id: '1a2b3c4d5e6f7g8h9i0j1k2l3m4n5o6p', type: 'topicGroup', ... }
 */
export const convertANode = (
  node,
  newNodeType,
  userId,
  position = { x: 0, y: 0 },
  selected = true,
  draggable = true,
  additionalProps = {},
) => {
  const newNode = {
    ...node,
    // id: node.id,
    type: newNodeType,
    position: position,
    data: {
      ...node.data,
      style: {
        ...node?.data?.style,
        ...DEFAULT_STYLES[newNodeType],
        ...(newNodeType === 'subtopic' && {
          backgroundColor: '#313030',
          color: '#ffffff',
          borderColor: '#BEBEBE',
        }),
      },
      ...(allowedGroupNodes.includes(newNodeType) && {
        headerStyle:
          node?.data?.headerStyle ||
          additionalProps?.headerStyle ||
          DEFAULT_HEADER_STYLES[newNodeType] ||
          DEFAULT_HEADER_STYLES['default'],
      }),
      prevType: node?.type,
    },
    selected: selected,
    draggable: draggable,
    ...additionalProps,
  };

  return newNode;
};

export const createNodeCopy = (offset, node, userId, additionalProps) => {
  const currentTime = `${Date.now()}`;
  const newNodeId = generateHash(
    `${userId}#${node.type}#${currentTime}#${secureRandomString(20)}`,
    32,
  );
  let newNode = {
    ...node,
    id: newNodeId,
    position: {
      x: node.parentId ? node.position.x : node.position.x + offset.x,
      y: node.parentId ? node.position.y : node.position.y + offset.y,
    },
    ...additionalProps,
  };
  return newNode;
};

/**
 * Dispatches a custom event on the `window` object.
 * - Allows different parts of the app to listen for and respond to events.
 * - Useful for communication between components that don't have direct prop/state relationships.
 *
 * @param {string} eventName - The name of the custom event.
 * @param {any} eventData - The data to be passed with the event.
 *
 * @example
 * // Emit a custom event
 * emitCustomEvent('userLoggedIn', { userId: 123 });
 *
 * // Listen for the event
 * window.addEventListener('userLoggedIn', (event) => {
 *
 * });
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/CustomEvent/CustomEvent
 */
export const emitCustomEvent = (eventName, eventData) => {
  const event = new CustomEvent(eventName, { detail: eventData });
  window.dispatchEvent(event);
};

/**
 *
 * @param {string} hex - Hex color code to check if it's dark or light
 * @returns a boolean value indecating if the color is dark or not
 */
export const isDarkColor = (hex) => {
  // If we don't have a hex value, try to handle other color formats
  if (!hex) return false;

  // Convert hex to RGB
  let r, g, b;

  if (hex.startsWith('#')) {
    const c = hex.substring(1);
    // Handle both #RGB and #RRGGBB formats
    if (c.length === 3) {
      r = parseInt(c[0] + c[0], 16);
      g = parseInt(c[1] + c[1], 16);
      b = parseInt(c[2] + c[2], 16);
    } else if (c.length === 6) {
      r = parseInt(c.substring(0, 2), 16);
      g = parseInt(c.substring(2, 4), 16);
      b = parseInt(c.substring(4, 6), 16);
    } else {
      return false; // Invalid hex format
    }
  } else {
    // For non-hex colors, default to considering them light
    return false;
  }

  // Calculate relative luminance using WCAG formula
  // https://www.w3.org/TR/WCAG20/#relativeluminancedef
  const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;

  // Lower threshold for better detection of light colors
  return luminance < 128;
};

export const addWatermark = (element, watermarkText) => {
  const watermark = document.createElement('div');
  watermark.textContent = watermarkText;
  watermark.style.position = 'absolute';
  watermark.style.top = '50%';
  watermark.style.left = '50%';
  watermark.style.transform = 'translate(-50%, -50%) rotate(-30deg)';
  watermark.style.fontSize = '80px';
  watermark.style.fontWeight = 'bold';
  watermark.style.color = 'rgba(0, 0, 0, 0.1)';
  watermark.style.whiteSpace = 'nowrap';
  watermark.style.zIndex = '20';

  element.appendChild(watermark);
};

export const addCopyright = (element) => {
  const copyrightText = document.createElement('div');
  copyrightText.textContent = '© 2026 SETU. All Rights Reserved.';
  copyrightText.style.position = 'absolute';
  copyrightText.style.bottom = '0';
  copyrightText.style.left = '50%';
  copyrightText.style.transform = 'translateX(-50%)';
  copyrightText.style.fontFamily = 'Arial, sans-serif';
  copyrightText.style.fontSize = '14px';
  copyrightText.style.fontWeight = 'bold';
  copyrightText.style.color = '#555';
  copyrightText.style.backgroundColor = 'rgba(255, 255, 255, 0.7)';
  copyrightText.style.padding = '5px 10px';
  copyrightText.style.borderRadius = '5px';
  copyrightText.style.width = '100%';
  copyrightText.style.textAlign = 'center';

  element.appendChild(copyrightText);
};

