export const getNodeTypeText = (nodeType) => {
  switch (nodeType) {
    case 'title':
      return 'Title / Complete Roadmap';
    case 'topic':
    case 'topicGroup':
      return 'Topic - Contains n modules';
    case 'subtopicGroup':
      return 'Module - Contains n chapters ';
    case 'subtopic':
      return 'A single chapter';
    case 'assignmentNode':
      return 'A single assignment';
    default:
      return nodeType;
  }
};

export const nodeHeaderHeights = new Map();

const rearrangeChildNodesLayoutSubtopicGroup = (
  nodes,
  parentNode,
  headingHeight = 70,
  type = undefined,
) => {
  if (!nodes) return;

  // Get all child nodes and sort them by y-position
  let parentChildren = nodes.filter((node) => node.parentId === parentNode.id);

  if (!type && type !== 'new-subtopic-add') {
    parentChildren = parentChildren.sort((a, b) => a.position.y - b.position.y);
  }
  if (parentChildren.length === 0) {
    return nodes.map((node) => {
      if (
        node.id === parentNode.id &&
        (node?.data?.prevType === 'subtopic' ||
          node?.data?.prevType === undefined)
      ) {
        // return {...node, type: 'subtopic', data: {...node.data, prevType: 'subtopicGroup',}}
        return convertANode(
          node,
          'subtopic',
          '',
          node.position,
          false,
          true,
          {},
        );
      }
      return node;
    });
  }
  let currentY = headingHeight + 30; // Position below heading
  let totalHeight = currentY;

  // Update child node positions
  const updatedChildren = parentChildren.map((node) => {
    const updatedNode = {
      ...node,
      position: { ...node.position, y: currentY },
    };
    currentY += (node.measured?.height || 50) + 25; // Move down by node height + gap
    totalHeight = currentY; // Track total occupied height
    return updatedNode;
  });

  // Ensure parent height is sufficient
  const minRequiredHeight = totalHeight + 80; // Extra padding
  // const newParentHeight = Math.max(parentNode.measured?.height || 100, minRequiredHeight);
  let newParentHeight = Math.max(headingHeight + 50, minRequiredHeight);
  // if(parentChildren.length === 0) {
  //   newParentHeight = nodeHeaderRef.current.offsetHeight;
  // }
  // Update parent node height if necessary

  return nodes.map((node) => {
    if (node.id === parentNode.id) {
      return {
        ...node,
        measured: { ...node.measured, height: newParentHeight },
        style: { ...node.style, height: newParentHeight },
        height: newParentHeight,
        data: {
          ...node.data,
          headerStyle: {
            ...node.data.headerStyle,
            height: headingHeight,
          },
        },
        // type: parentChildren.length === 0 ? 'subtopic': 'subtopicGroup'
      };
    }
    return updatedChildren.find((updated) => updated.id === node.id) || node;
  });
};

const rearrangeChildNodesLayoutTopicGroup = (
  nodes,
  parentNode,
  headingHeight = 70,
) => {
  if (!nodes) return;

  // Get all child nodes and sort them by y-position
  const parentChildren = nodes.filter(
    (node) => node.parentId === parentNode.id,
  );
  // .sort((a, b) => a.position.y - b.position.y);

  console.log("[DEBUG]: Parent children map: ", parentChildren)
  if (parentChildren.length === 0) {
    return nodes.map((node) => {
      if (
        node.id === parentNode.id &&
        (node?.data?.prevType === 'topic' || node?.data?.prevType === undefined)
      ) {
        // return {...node, type: 'subtopic', data: {...node.data, prevType: 'subtopicGroup',}}

        return convertANode(node, 'topic', '', node.position, false, true, {});
      }
      return node;
    });
  }
  let currentY = headingHeight + 20; // Position below heading
  let totalHeight = currentY;

  // Update child node positions
  const updatedChildren = parentChildren.map((node) => {
    const updatedNode = {
      ...node,
      position: { ...node.position, y: currentY },
    };
    currentY += (node.measured?.height || 50) + 10; // Move down by node height + gap
    totalHeight = currentY; // Track total occupied height
    return updatedNode;
  });

  console.log("[DEBUG]: Updated children: ", updatedChildren)

  // Ensure parent height is sufficient
  const minRequiredHeight = totalHeight + 20; // Extra padding
  // const newParentHeight = Math.max(parentNode.measured?.height || 100, minRequiredHeight);
  let newParentHeight = Math.max(headingHeight + 50, minRequiredHeight);
  // if(parentChildren.length === 0) {
  //   newParentHeight = nodeHeaderRef.current.offsetHeight;
  // }
  // Update parent node height if necessary

  return nodes.map((node) => {
    if (node.id === parentNode.id) {
      return {
        ...node,
        measured: { ...node.measured, height: newParentHeight },
        style: { ...node.style, height: newParentHeight },
        height: newParentHeight,
        data: {
          ...node.data,
          headerStyle: {
            ...node.data.headerStyle,
            height: headingHeight,
          },
        },
        // type: parentChildren.length === 0 ? 'subtopic': 'subtopicGroup'
      };
    }
    return updatedChildren.find((updated) => updated.id === node.id) || node;
  });
};

export const rearrangeChildNodesLayoutGlobal = (
  nodes,
  parentNode,
  headingHeight = 70,
  type = undefined,
) => {
  console.log('Rerrange called.....');
  let updatedNodes = nodes;
  // headingHeight = nodeHeaderHeights.get(parentNode.id) || 70;
  if (parentNode.type === 'topicGroup') {
    console.log('[DEBUG]: Rearranging topicgroup....')
    console.log('[DEBUG]: Heading height: ', headingHeight)
    updatedNodes = rearrangeChildNodesLayoutTopicGroup(
      nodes,
      parentNode,
      headingHeight,
    );
  }
  if (parentNode.type === 'subtopicGroup') {
    console.log('subtopicGroup rearrange called....');
    updatedNodes = rearrangeChildNodesLayoutSubtopicGroup(
      nodes,
      parentNode,
      headingHeight,
    );
  }
  return updatedNodes;
};

export const resolveAllOverlapsBlockwise = (nodes, edges) => {
  const SPACING_BETWEEN_BLOCKS = 60;
  const SIDE_NODE_SPACING = 80;

  let updatedNodes = [...nodes];

  // Helper: Get children of a topic block using the latest updatedNodes
  const getBlockChildren = (topicId) => {
    const childIds = edges
      .filter((e) => e.source === topicId && e.type !== 'straight')
      .map((e) => e.target);

    return updatedNodes.filter(
      (n) =>
        childIds.includes(n.id) &&
        ['subtopic', 'subtopicGroup', 'assignmentNode'].includes(n.type),
    );
  };

  // Resolve vertical overlaps between subtopic/subtopicGroup nodes in the same x group
  const resolveSideNodeOverlapInBlock = (blockChildren) => {
    let hasOverlap = true;

    while (hasOverlap) {
      hasOverlap = false;

      const groupedByX = blockChildren.reduce((acc, node) => {
        if (node.type === 'subtopicGroup' || node.type === 'subtopic') {
          const key = node.position.x;
          if (!acc[key]) acc[key] = [];
          acc[key].push(node);
        }
        return acc;
      }, {});

      Object.values(groupedByX).forEach((group) => {
        group.sort((a, b) => a.position.y - b.position.y);

        for (let i = 1; i < group.length; i++) {
          const prev = group[i - 1];
          const curr = group[i];

          const prevBottom = prev.position.y + (prev.measured?.height || 200);
          const gap = curr.position.y - prevBottom;

          if (gap < SIDE_NODE_SPACING) {
            const delta = SIDE_NODE_SPACING - gap;

            const index = updatedNodes.findIndex((n) => n.id === curr.id);
            updatedNodes[index] = {
              ...curr,
              position: {
                ...curr.position,
                y: curr.position.y + delta,
              },
            };
            hasOverlap = true;
          }
        }
      });

      // Re-fetch children after potential position updates
      blockChildren = blockChildren.map((child) =>
        updatedNodes.find((n) => n.id === child.id),
      );
    }
  };

  const topicNodes = updatedNodes
    .filter(
      (n) =>
        n.type === 'topic' ||
        n.type === 'topicGroup' ||
        n.type === 'learningAnchor' ||
        (n.type === 'assignmentNode' && !n?.parentId)
    )
    .sort((a, b) => a.position.y - b.position.y);

  console.log("[DEBUG]: Spine nodes: ", topicNodes)

  for (let i = 0; i < topicNodes.length; i++) {
    const block = updatedNodes.find((n) => n.id === topicNodes[i].id);

    // 1. Resolve side node overlaps for this block
    let blockChildren = getBlockChildren(block.id);
    resolveSideNodeOverlapInBlock(blockChildren);

    // Refresh children after any position changes
    blockChildren = getBlockChildren(block.id);

    // 2. Resolve vertical block overlap with next block
    if (i < topicNodes.length - 1) {
      const nextBlock = updatedNodes.find((n) => n.id === topicNodes[i + 1].id);
      let nextChildren = getBlockChildren(nextBlock.id);

      const blockBottomY =
        blockChildren.length > 0
          ? Math.max(
              ...blockChildren.map(
                (n) => n.position.y + (n.measured?.height || 200),
              ),
            )
          : block.position.y + (block.measured?.height || 200);

      const nextTopY = Math.min(
        nextBlock.position.y,
        ...(nextChildren.map((n) => n.position.y) || []),
      );

      const offsetNeeded = blockBottomY + SPACING_BETWEEN_BLOCKS - nextTopY;

      if (offsetNeeded > 0) {
        // Move next block and its children down
        [nextBlock, ...nextChildren].forEach((n) => {
          const index = updatedNodes.findIndex((x) => x.id === n.id);
          updatedNodes[index] = {
            ...updatedNodes[index],
            position: {
              ...updatedNodes[index].position,
              y: updatedNodes[index].position.y + offsetNeeded,
            },
          };
        });

        // Update topicNodes for future comparisons
        topicNodes[i + 1] = {
          ...topicNodes[i + 1],
          position: { ...topicNodes[i + 1].position, y: topicNodes[i + 1].position.y + offsetNeeded },
        };
      }
    }
  }

  return updatedNodes;
};
